document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("sphere-form"),t=document.getElementById("sphere-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("sphere-r").value);if(n<=0)return t.textContent="Please enter a positive radius.",void 0;const o=4*Math.PI*n*n,r=4/3*Math.PI*n*n*n;t.innerHTML=`<b>Surface Area:</b> ${o.toFixed(4)}<br><b>Volume:</b> ${r.toFixed(4)}`})});